css:
& { padding:0; isolation:isolate; overflow:hidden; }
.ba-head { position:absolute; left:100px; top:80px; right:100px; }
.ba-head p { font-size:22px; color:var(--accent); letter-spacing:.12em; }
.ba-head h2 { margin-top:18px; max-width:42ch; font-size:64px; line-height:1.08; text-wrap:balance; }
.ba-head :empty { display:none; }
.ba-picture { position:absolute; left:100px; top:335px; width:790px; height:485px; margin:0; }
.ba-picture img { width:100%; height:100%; object-fit:contain; }
.ba-picture:has(img[src=""]) { display:none; }
.ba-context { position:absolute; left:100px; top:860px; width:790px; font-size:27px; line-height:1.4; color:var(--muted); }
.ba-items { position:absolute; left:1010px; right:100px; top:335px; bottom:160px; margin:0; padding:0; list-style:none; }
.assumption { position:absolute; inset:0; opacity:0!important; visibility:hidden; border-top:3px solid var(--accent); padding-top:30px; transition:opacity .55s ease; }
.assumption.in:not(:has(~.assumption.in)) { opacity:1!important; visibility:inherit; }
.assumption>b { display:block; font-size:44px; line-height:1.2; max-width:28ch; font-weight:550; }
.assumption-answer { position:absolute; width:0; height:0; overflow:hidden; }
.assumption-result { margin-top:44px; opacity:0; visibility:hidden; transition:opacity .45s ease; }
.assumption:has(.assumption-answer.in) .assumption-result { opacity:1; visibility:inherit; }
.assumption-result strong { display:block; font-size:66px; line-height:1.05; color:var(--accent); overflow-wrap:anywhere; }
.assumption-result p { margin-top:22px; font-size:28px; line-height:1.4; color:var(--muted); }
.ba-end { position:absolute; left:100px; right:100px; bottom:85px; font-size:30px; opacity:0; transition:opacity .45s; }
[data-template-end] { position:absolute; width:0; height:0; overflow:hidden; }
&:has([data-template-end].in,[data-template-end]:not([data-step])) .ba-items { display:flex; flex-direction:column; gap:25px; top:320px; bottom:auto; }
&:has([data-template-end].in,[data-template-end]:not([data-step])) .assumption { position:relative; inset:auto; opacity:1!important; visibility:inherit; padding-top:20px; }
&:has([data-template-end].in,[data-template-end]:not([data-step])) .assumption>b { font-size:29px; }
&:has([data-template-end].in,[data-template-end]:not([data-step])) .assumption-result { opacity:1; visibility:inherit; margin-top:16px; }
&:has([data-template-end].in,[data-template-end]:not([data-step])) .assumption-result strong { font-size:43px; }
&:has([data-template-end].in,[data-template-end]:not([data-step])) .assumption-result p { font-size:23px; margin-top:10px; }
&:has([data-template-end].in,[data-template-end]:not([data-step])) .ba-end { opacity:1; }
&:has(.assumption:nth-child(3)) .assumption-result p { font-size:22px; }
&[data-body-motion="none"] * { transition:none!important; }
@media(prefers-reduced-motion:reduce) { & * { transition:none!important; } }

&:has(.ba-picture img[src=""]) .ba-items { left:100px; }
&:has(.ba-picture img[src=""]) .ba-context { top:auto; bottom:150px; width:80%; }

.assumption-window { position:absolute; left:-910px; top:-3px; width:790px; height:485px; overflow:hidden; pointer-events:none; }
.assumption-window i { position:absolute; display:block; box-shadow:0 0 0 1400px var(--bg); border-radius:16px; }
&:has([data-template-end].in,[data-template-end]:not([data-step])) .assumption-window { display:none; }
